19	    throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
20	  }
21	  const [metric, minStr] = parts;
22	  const min = Number.parseFloat(minStr);
23	  if (Number.isNaN(min)) {
24	    throw new Error(`Invalid threshold minimum value: "${minStr}". Expected a number.`);
25	  }
26	  if (min < 0 || min > 1) {
27	    throw new Error(`Threshold minimum must be between 0 and 1, got: ${min}`);
28	  }
29	  return { metric, min };
30	}
31	
32	export function validateThresholds(thresholds, availableMetricIds) {
33	  const errors = [];
34	  const parsed = [];
35	  for (const threshold of thresholds) {
36	    try {
37	      const { metric, min } = parseThreshold(threshold);
38	      if (!availableMetricIds.includes(metric)) {
39	        errors.push(`Unknown metric: "${metric}". Valid metrics: ${availableMetricIds.join(', ')}`);
40	      } else {
41	        parsed.push({ metric, min });
42	      }
43	    } catch (error) {
44	      errors.push(error.message);
45	    }
46	  }
47	  return { parsed, errors };
48	}
49	
50	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
51	  if (!outputsPath) {
52	    throw new Error('outputsPath is required for evaluation.');
53	  }
54	
55	  const outputsAbsolute = path.resolve(outputsPath);
56	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
57	  const outputs = JSON.parse(outputsRaw);
58	
59	  let references = [];
60	  let referencesAbsolute = null;
61	  if (referencesPath) {
62	    referencesAbsolute = path.resolve(referencesPath);
63	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
64	    references = JSON.parse(referencesRaw);
65	  }
66	
67	  return {
68	    outputs,
69	    references,
70	    outputsPath: outputsAbsolute,
71	    referencesPath: referencesAbsolute
72	  };
73	}
74	
75	export function runEvaluations({
76	  outputs,
77	  references,
78	  metrics = DEFAULT_METRICS
79	} = {}) {
80	  const outs = ensureArray(outputs);
81	  const refs = ensureArray(references);
82	
83	  const evaluations = metrics.map((metric) => {
84	    if (typeof metric === 'function') {
85	      return metric(outs, refs);
86	    }
87	    if (metric && typeof metric.evaluate === 'function') {
88	      return metric.evaluate(outs, refs);
89	    }
90	    throw new Error('Invalid metric supplied to runEvaluations.');
91	  });
92	
93	  return evaluations;
94	}
95	
96	export function generateReport({
97	  evaluations,
98	  outputsPath,
99	  referencesPath,
100	  generatedAt = new Date().toISOString(),
101	  thresholds
102	}) {
103	  const totalSamples = evaluations.reduce((total, metric) => {
104	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
105	    return total;
106	  }, 0);
107	
108	  const report = {
109	    metadata: {
110	      generatedAt,
111	      outputsPath,
112	      referencesPath,
113	      totalSamples
114	    },
115	    metrics: evaluations
116	  };
117	
118	  if (thresholds && thresholds.length > 0) {
119	    const thresholdResults = [];
120	    let allPassed = true;
121	    for (const { metric: metricId, min } of thresholds) {
122	      const metric = evaluations.find((m) => m.id === metricId);
123	      const score = metric?.score ?? null;
124	      const passed = score !== null && score >= min;
125	      if (!passed) allPassed = false;
126	      thresholdResults.push({
127	        metric: metricId,
128	        min,
129	        score,
130	        passed
131	      });
132	    }
133	    report.passed = allPassed;
134	    report.thresholds = thresholdResults;
135	  }
136	
137	  return report;
138	}
139	
140	export function writeReport({
141	  report,
142	  format = 'json',
143	  reportPath,
144	  fs: fsModule = defaultFs
145	}) {
146	  const resolved = resolveReportPath(reportPath, format);
147	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
148	  fsModule.writeFileSync(resolved, payload, 'utf8');
149	  return resolved;
150	}
151	
152	export {
153	  DEFAULT_METRICS,
154	  exactMatchMetric,
155	  toxicityMetric,
156	  lengthVarianceMetric
157	};
158	
159	export default {
160	  loadDataset,
161	  runEvaluations,
162	  generateReport,
163	  writeReport,
164	  parseThreshold,
165	  validateThresholds,
166	  DEFAULT_METRICS,
167	  exactMatchMetric,
168	  toxicityMetric,
169	  lengthVarianceMetric
170	};
