import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function parseThreshold(thresholdStr) {
  const parts = thresholdStr.split('=');
  if (parts.length !== 2) {
    throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
  }
  const [metric, minStr] = parts;
  const min = Number.parseFloat(minStr);
  if (Number.isNaN(min)) {
    throw new Error(`Invalid threshold minimum value: "${minStr}". Expected a number.`);
  }
  if (min < 0 || min > 1) {
    throw new Error(`Threshold minimum must be between 0 and 1, got: ${min}`);
  }
  return { metric, min };
}

export function validateThresholds(thresholds, availableMetricIds) {
  const errors = [];
  const parsed = [];
  for (const threshold of thresholds) {
    try {
      const { metric, min } = parseThreshold(threshold);
      if (!availableMetricIds.includes(metric)) {
        errors.push(`Unknown metric: "${metric}". Valid metrics: ${availableMetricIds.join(', ')}`);
      } else {
        parsed.push({ metric, min });
      }
    } catch (error) {
      errors.push(error.message);
    }
  }
  return { parsed, errors };
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && thresholds.length > 0) {
    const thresholdResults = [];
    let allPassed = true;
    for (const { metric: metricId, min } of thresholds) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= min;
      if (!passed) allPassed = false;
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed
      });
    }
    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  parseThreshold,
  validateThresholds,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

