  it('parses valid thresholds', () => {
    const threshold1 = parseThreshold('exact_match=0.9');
    expect(threshold1).toEqual({ metric: 'exact_match', min: 0.9 });

    const threshold2 = parseThreshold('toxicity=0.5');
    expect(threshold2).toEqual({ metric: 'toxicity', min: 0.5 });
  });

  it('rejects malformed thresholds', () => {
    expect(() => parseThreshold('exact_match')).toThrow(/Invalid threshold format/);
    expect(() => parseThreshold('exact_match=not_a_number')).toThrow(/Invalid threshold minimum value/);
    expect(() => parseThreshold('exact_match=1.5')).toThrow(/between 0 and 1/);
    expect(() => parseThreshold('exact_match=-0.1')).toThrow(/between 0 and 1/);
  });

  it('validates thresholds against available metrics', () => {
    const availableMetrics = ['exact_match', 'toxicity', 'length_variance'];
    const { parsed, errors } = validateThresholds(['exact_match=0.9', 'toxicity=0.8'], availableMetrics);
    expect(parsed).toHaveLength(2);
    expect(errors).toHaveLength(0);
  });

  it('reports errors for unknown metrics', () => {
    const availableMetrics = ['exact_match', 'toxicity', 'length_variance'];
    const { parsed, errors } = validateThresholds(['unknown_metric=0.9'], availableMetrics);
    expect(parsed).toHaveLength(0);
    expect(errors).toHaveLength(1);
    expect(errors[0]).toMatch(/Unknown metric/);
  });

  it('generates report with passing thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const thresholds = [
      { metric: 'exact_match', min: 0.5 },
      { metric: 'toxicity', min: 0.9 }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds.every((t) => t.passed)).toBe(true);
  });

  it('generates report with failing thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const thresholds = [{ metric: 'exact_match', min: 0.95 }];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('handles metrics without scores in thresholds', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0,
        matches: 0,
        details: 'No references provided'
      }
    ];
    const thresholds = [{ metric: 'exact_match', min: 0.5 }];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBe(null);
  });
